tests.script:
// 场景准备：确认页面已加载，无任务存在
const initialTotal = await page.evaluate(() => window.app.getDerived().total);
assert.equal(initialTotal, 0, '初始任务总数应为0');

// 前置操作（非witness）：在输入框填入有效文本
await page.fill('#task-input', '学习 TypeScript');

// witness：点击新增按钮，total 从 0 变为 1
await runtimeWitness(page, {
  getter: 'window.app.getDerived',
  state_path: 'total',
  action: { kind: 'click', selector: '#btn-add' },
  view: { kind: 'number', selector: '#stat-total' }
});

// 断言：任务成功出现在列表中
const taskItems = await page.locator('.task-item').count();
assert.equal(taskItems, 1, '列表中应出现1条任务');

// 断言：任务文本正确显示
const taskText = await page.locator('.task-item .task-text').textContent();
assert.equal(taskText, '学习 TypeScript', '任务文本应为输入的有效内容');

// 断言：输入框已清空
const inputValue = await page.locator('#task-input').inputValue();
assert.equal(inputValue, '', '新增成功后输入框应清空');

// 断言：统计数字更新正确
const derived = await page.evaluate(() => window.app.getDerived());
assert.equal(derived.total, 1, '总数应为1');
assert.equal(derived.activeCount, 1, '未完成数应为1');
assert.equal(derived.doneCount, 0, '已完成数应为0');

// 确认初始无任务
const initialTotal = await page.evaluate(() => window.app.getDerived().total);
assert.equal(initialTotal, 0, '初始任务总数应为0');

// 前置操作：填入中文文本并聚焦输入框
await page.fill('#task-input', '买牛奶和面包');

// 通过键盘回车提交
await page.locator('#task-input').press('Enter');

// 等待渲染完成
await page.waitForTimeout(100);

// 断言：任务出现在列表中
const taskItems = await page.locator('.task-item').count();
assert.equal(taskItems, 1, '回车后列表中应出现1条任务');

// 断言：任务文本正确
const taskText = await page.locator('.task-item .task-text').textContent();
assert.equal(taskText, '买牛奶和面包', '任务文本应为输入的中文内容');

// 断言：输入框已清空
const inputValue = await page.locator('#task-input').inputValue();
assert.equal(inputValue, '', '回车新增成功后输入框应清空');

// 断言：状态正确更新
const derived = await page.evaluate(() => window.app.getDerived());
assert.equal(derived.total, 1, '总数应为1');
assert.equal(derived.activeCount, 1, '未完成数应为1');
assert.equal(derived.doneCount, 0, '已完成数应为0');

// 用 witness 再次验证通过回车添加第二条任务也有效
await page.fill('#task-input', '写周报');
await runtimeWitness(page, {
  getter: 'window.app.getDerived',
  state_path: 'total',
  action: { kind: 'click', selector: '#btn-add' },
  view: { kind: 'number', selector: '#stat-total' }
});

// 确认第二条也成功添加
const finalCount = await page.locator('.task-item').count();
assert.equal(finalCount, 2, '两次添加后列表应有2条任务');

// 初始状态确认
assert.equal(await page.evaluate(() => window.app.getDerived().total), 0);

// 第一次：通过按钮添加
await page.fill('#task-input', '任务一');
await runtimeWitness(page, {
  getter: 'window.app.getDerived',
  state_path: 'total',
  action: { kind: 'click', selector: '#btn-add' },
  view: { kind: 'number', selector: '#stat-total' }
});

// 第二次：通过回车添加
await page.fill('#task-input', '任务二');
await page.locator('#task-input').press('Enter');
await page.waitForTimeout(100);

// 第三次：再次通过按钮添加（含特殊字符）
await page.fill('#task-input', '修复Bug#123');
await runtimeWitness(page, {
  getter: 'window.app.getDerived',
  state_path: 'total',
  action: { kind: 'click', selector: '#btn-add' },
  view: { kind: 'number', selector: '#stat-total' }
});

// 断言：3条任务全部出现
const taskItems = await page.locator('.task-item');
assert.equal(await taskItems.count(), 3, '应有3条任务');

// 断言：文本均正确
const texts = await taskItems.locator('.task-text').allTextContents();
assert.equal(texts[0], '任务一');
assert.equal(texts[1], '任务二');
assert.equal(texts[2], '修复Bug#123');

// 断言：输入框最终为空
assert.equal(await page.locator('#task-input').inputValue(), '', '最终输入框应为空');

// 断言：统计正确
const d = await page.evaluate(() => window.app.getDerived());
assert.equal(d.total, 3);
assert.equal(d.activeCount, 3);
assert.equal(d.doneCount, 0);

// 确认错误信息区域初始隐藏或为空
const initialError = await page.evaluate(() => {
  const el = document.getElementById('error-msg');
  return { hidden: el ? el.hidden : true, text: el ? el.textContent : '' };
});
assert.ok(initialError.hidden || initialError.text === '', '初始错误提示应为隐藏或空');

// 输入有效文本并点击新增
await page.fill('#task-input', '有效任务内容');
await runtimeWitness(page, {
  getter: 'window.app.getDerived',
  state_path: 'total',
  action: { kind: 'click', selector: '#btn-add' },
  view: { kind: 'number', selector: '#stat-total' }
});

// 断言：新增成功后无错误提示
const errorState = await page.evaluate(() => {
  const el = document.getElementById('error-msg');
  return { hidden: el ? el.hidden : true, text: el ? el.textContent : '' };
});
assert.ok(errorState.hidden || errorState.text === '', '有效新增后不应显示错误提示');

// 断言：任务确实出现在列表
assert.equal(await page.locator('.task-item').count(), 1, '列表中应有1条任务');
assert.equal(await page.locator('.task-item .task-text').textContent(), '有效任务内容');

// 输入含中间空格的文本（不是首尾空白，应通过验证）
await page.fill('#task-input', 'hello world');

await runtimeWitness(page, {
  getter: 'window.app.getDerived',
  state_path: 'total',
  action: { kind: 'click', selector: '#btn-add' },
  view: { kind: 'number', selector: '#stat-total' }
});

// 断言：任务出现且文本保留中间空格
const taskText = await page.locator('.task-item .task-text').textContent();
assert.equal(taskText, 'hello world', '中间空格应保留');

// 断言：输入框清空
assert.equal(await page.locator('#task-input').inputValue(), '', '输入框应清空');

// 断言：无错误提示
const errHidden = await page.evaluate(() => document.getElementById('error-msg').hidden);
assert.ok(errHidden, '不应显示错误');

// 确认初始total为0
const beforeFill = await page.evaluate(() => window.app.getDerived().total);
assert.equal(beforeFill, 0, '初始total应为0');

// fill操作不改变total（仅准备场景）
await page.fill('#task-input', '准备中的任务');
const afterFill = await page.evaluate(() => window.app.getDerived().total);
assert.equal(afterFill, 0, 'fill后total仍为0，证明fill不是witness');

// click操作改变total（真正的witness）
await runtimeWitness(page, {
  getter: 'window.app.getDerived',
  state_path: 'total',
  action: { kind: 'click', selector: '#btn-add' },
  view: { kind: 'number', selector: '#stat-total' }
});

// click后total变为1
const afterClick = await page.evaluate(() => window.app.getDerived().total);
assert.equal(afterClick, 1, 'click后total应为1');

// 列表有任务
assert.equal(await page.locator('.task-item').count(), 1);

// 输入框清空
assert.equal(await page.locator('#task-input').inputValue(), '');

await page.fill('#task-input', '  学习  ');
await page.click('#btn-add');
const items = page.locator('.task-item');
await items.first().waitFor({ state: 'visible', timeout: 5000 });
const textContent = await page.locator('.task-item .task-text').first().textContent();
assert.equal(textContent, '学习', '去除首尾空白后应展示"学习"，实际为: ' + JSON.stringify(textContent));
const totalNum = await page.locator('#stat-total').textContent();
assert.equal(totalNum, '1', '应显示1条任务');

await page.fill('#task-input', '\t\n  复杂任务  \t\n');
await page.click('#btn-add');
const items = page.locator('.task-item');
await items.first().waitFor({ state: 'visible', timeout: 5000 });
const textContent = await page.locator('.task-item .task-text').first().textContent();
assert.equal(textContent, '复杂任务', '制表符/换行首尾应被去除，实际为: ' + JSON.stringify(textContent));

await page.fill('#task-input', '\u00A0\u00A0测试NBSP\u00A0\u00A0');
await page.click('#btn-add');
const items = page.locator('.task-item');
await items.first().waitFor({ state: 'visible', timeout: 5000 });
const textContent = await page.locator('.task-item .task-text').first().textContent();
assert.equal(textContent, '测试NBSP', '非断行空格首尾应被去除，实际为: ' + JSON.stringify(textContent));

await page.fill('#task-input', '\uFEFF\uFEFFBOM文本\uFEFF');
await page.click('#btn-add');
const items = page.locator('.task-item');
await items.first().waitFor({ state: 'visible', timeout: 5000 });
const textContent = await page.locator('.task-item .task-text').first().textContent();
assert.equal(textContent, 'BOM文本', 'Unicode BOM首尾应被去除，实际为: ' + JSON.stringify(textContent));

await page.fill('#task-input', '   回车trim测试   ');
await page.press('#task-input', 'Enter');
const items = page.locator('.task-item');
await items.first().waitFor({ state: 'visible', timeout: 5000 });
const textContent = await page.locator('.task-item .task-text').first().textContent();
assert.equal(textContent, '回车trim测试', '回车提交时首尾空白也应被去除，实际为: ' + JSON.stringify(textContent));

await page.fill('#task-input', '  持久化trim  ');
await page.click('#btn-add');
const items = page.locator('.task-item');
await items.first().waitFor({ state: 'visible', timeout: 5000 });
const stored = await page.evaluate(() => {
  const raw = localStorage.getItem('task-list-data');
  if (!raw) return null;
  return JSON.parse(raw);
});
assert.ok(stored, 'localStorage应包含task-list-data');
const tasksArr = Array.isArray(stored) ? stored : stored.tasks;
assert.ok(Array.isArray(tasksArr) && tasksArr.length >= 1, '存储中应有至少一条任务');
const lastTask = tasksArr[tasksArr.length - 1];
assert.equal(lastTask.text, '持久化trim', 'localStorage持久化文本应为去除首尾空白后的值，实际为: ' + JSON.stringify(lastTask.text));

await page.fill('#task-input', '  刷新验证  ');
await page.click('#btn-add');
await page.locator('.task-item .task-text').first().waitFor({ state: 'visible', timeout: 5000 });
await page.reload();
await page.locator('.task-item .task-text').first().waitFor({ state: 'visible', timeout: 5000 });
const textAfterReload = await page.locator('.task-item .task-text').first().textContent();
assert.equal(textAfterReload, '刷新验证', '刷新后恢复的文本应为去除首尾空白后的值，实际为: ' + JSON.stringify(textAfterReload));

await page.waitForSelector('#btn-add');

// 确认初始状态为 0 个任务
const initialTotal = await page.locator('#stat-total').textContent();
assert.equal(initialTotal, '0');

// 填入空字符串并点击新增
await page.fill('#task-input', '');
await page.click('#btn-add');
await page.waitForTimeout(150);

// 总数仍为 0，任务未增加
const total = await page.locator('#stat-total').textContent();
assert.equal(total, '0');

// 列表中无任务项
const taskItems = await page.locator('.task-item').count();
assert.equal(taskItems, 0);

// 错误提示可见且含可理解的中文文字
const errorMsgVisible = await page.locator('#error-msg').isVisible();
assert.ok(errorMsgVisible, '错误提示应当可见');
const errorText = await page.locator('#error-msg').textContent();
assert.ok(errorText.length > 0, '错误提示应有文字内容');
// 验证是中文可理解文案（包含'不能为空'或类似关键词）
const hasChineseError = /[\u4e00-\u9fff]/.test(errorText);
assert.ok(hasChineseError, '错误提示应为中文可理解文案: ' + errorText);

await page.waitForSelector('#btn-add');

const initialTotal = await page.locator('#stat-total').textContent();
assert.equal(initialTotal, '0');

// 填入多个空格并点击新增
await page.fill('#task-input', '     ');
await page.click('#btn-add');
await page.waitForTimeout(150);

// 总数仍为 0
const total = await page.locator('#stat-total').textContent();
assert.equal(total, '0');

// 无任务项
const taskItems = await page.locator('.task-item').count();
assert.equal(taskItems, 0);

// 错误提示可见且为中文
const errorMsgVisible = await page.locator('#error-msg').isVisible();
assert.ok(errorMsgVisible, '纯空格输入后错误提示应可见');
const errorText = await page.locator('#error-msg').textContent();
assert.ok(errorText.length > 0);
assert.ok(/[\u4e00-\u9fff]/.test(errorText), '应为中文可理解提示: ' + errorText);

await page.waitForSelector('#btn-add');

const initialTotal = await page.locator('#stat-total').textContent();
assert.equal(initialTotal, '0');

// 填入制表符、换行、回车等混合空白
await page.fill('#task-input', '\t\n\r  \t');
await page.click('#btn-add');
await page.waitForTimeout(150);

// 总数仍为 0，任务未增加
const total = await page.locator('#stat-total').textContent();
assert.equal(total, '0');

const taskItems = await page.locator('.task-item').count();
assert.equal(taskItems, 0);

// 错误提示可见且为中文
const errorMsgVisible = await page.locator('#error-msg').isVisible();
assert.ok(errorMsgVisible, '混合空白输入后错误提示应可见');
const errorText = await page.locator('#error-msg').textContent();
assert.ok(errorText.length > 0);
assert.ok(/[\u4e00-\u9fff]/.test(errorText), '应为中文可理解提示: ' + errorText);

await page.waitForSelector('#btn-add');

// 先正常添加一条有效任务建立前置状态
await page.fill('#task-input', '有效任务');
await page.click('#btn-add');
await page.waitForTimeout(150);

// 确认已有 1 条任务
const totalBefore = await page.locator('#stat-total').textContent();
assert.equal(totalBefore, '1');

// 现在尝试用纯空格新增
await page.fill('#task-input', '  \t ');
await page.click('#btn-add');
await page.waitForTimeout(150);

// 总数仍为 1，不因空白输入增加
const totalAfter = await page.locator('#stat-total').textContent();
assert.equal(totalAfter, '1');

// 列表中仍然只有 1 条任务
const taskItems = await page.locator('.task-item').count();
assert.equal(taskItems, 1);

// 错误提示可见
const errorMsgVisible = await page.locator('#error-msg').isVisible();
assert.ok(errorMsgVisible, '已有任务时空白输入仍应显示错误提示');
const errorText = await page.locator('#error-msg').textContent();
assert.ok(errorText.length > 0);
assert.ok(/[\u4e00-\u9fff]/.test(errorText), '应为中文可理解提示: ' + errorText);

// 原有任务文本未被篡改
const firstTaskText = await page.locator('.task-item .task-text').first().textContent();
assert.equal(firstTaskText, '有效任务');

await page.waitForSelector('#btn-add');

const initialTotal = await page.locator('#stat-total').textContent();
assert.equal(initialTotal, '0');

// 聚焦输入框，输入纯空格后按回车
await page.click('#task-input');
await page.fill('#task-input', '  ');
await page.keyboard.press('Enter');
await page.waitForTimeout(150);

// 总数仍为 0
const total = await page.locator('#stat-total').textContent();
assert.equal(total, '0');

const taskItems = await page.locator('.task-item').count();
assert.equal(taskItems, 0);

// 错误提示可见且为中文可理解文案
const errorMsgVisible = await page.locator('#error-msg').isVisible();
assert.ok(errorMsgVisible, '回车提交空白输入应显示错误提示');
const errorText = await page.locator('#error-msg').textContent();
assert.ok(errorText.length > 0);
assert.ok(/[\u4e00-\u9fff]/.test(errorText), '应为中文可理解提示: ' + errorText);

// 场景准备：新增一条任务
await page.fill('#task-input', '学习 TypeScript');
await page.click('#btn-add');

// 验证任务出现在列表
const firstItem = page.locator('.task-item').first();
await firstItem.waitFor({ state: 'visible' });
const textBefore = await firstItem.locator('.task-text').textContent();
assert.equal(textBefore, '学习 TypeScript');

// 验证切换按钮初始状态为"未完成"
const toggleBtn = firstItem.locator('.task-toggle');
const btnTextBefore = await toggleBtn.textContent();
assert.equal(btnTextBefore, '未完成任务');

// 验证 aria-pressed 初始为 false
const ariaBefore = await toggleBtn.getAttribute('aria-pressed');
assert.equal(ariaBefore, 'false');

// witness: 点击切换 → doneCount 0→1, #stat-done 0→1
await runtimeWitness(page, {
  getter: 'window.app.getDerived',
  state_path: 'doneCount',
  action: { kind: 'click', selector: '.task-item:first-child .task-toggle' },
  view: { kind: 'number', selector: '#stat-done' }
});

// 业务断言：任务文本不变
const itemAfter = page.locator('.task-item').first();
const textAfter = await itemAfter.locator('.task-text').textContent();
assert.equal(textAfter, '学习 TypeScript', 'AC-004: 切换后任务文本应保持不变');

// 业务断言：按钮文本变为"已完成"
const btnTextAfter = await itemAfter.locator('.task-toggle').textContent();
assert.equal(btnTextAfter, '已完成任务', 'AC-004: 切换后按钮应显示已完成');

// 业务断言：aria-pressed 变为 true
const ariaAfter = await itemAfter.locator('.task-toggle').getAttribute('aria-pressed');
assert.equal(ariaAfter, 'true', 'AC-004: aria-pressed 应反映完成状态');

// 业务断言：li 具有 done class（列表展示更新）
const itemClass = await itemAfter.getAttribute('class');
assert.ok(itemClass.includes('done'), 'AC-004: 任务项应标记 done 样式类');

// 业务断言：未完成统计归零
const activeStat = await page.locator('#stat-active').textContent();
assert.equal(activeStat, '0');

// 场景准备：新增一条任务并切换为已完成
await page.fill('#task-input', '买菜购物');
await page.click('#btn-add');

const firstItem = page.locator('.task-item').first();
await firstItem.waitFor({ state: 'visible' });

// 先切换为已完成
await page.click('.task-item:first-child .task-toggle');

// 确认当前为已完成状态
let textBefore = await firstItem.locator('.task-text').textContent();
assert.equal(textBefore, '买菜购物');
let btnText = await firstItem.locator('.task-toggle').textContent();
assert.equal(btnText, '已完成任务');

// witness: 再次点击切换 → activeCount 0→1, #stat-active 0→1
await runtimeWitness(page, {
  getter: 'window.app.getDerived',
  state_path: 'activeCount',
  action: { kind: 'click', selector: '.task-item:first-child .task-toggle' },
  view: { kind: 'number', selector: '#stat-active' }
});

// 业务断言：任务文本不变
const itemAfter = page.locator('.task-item').first();
const textAfter = await itemAfter.locator('.task-text').textContent();
assert.equal(textAfter, '买菜购物', 'AC-004: 回退切换后任务文本应保持不变');

// 业务断言：按钮文本恢复"未完成"
const btnTextAfter = await itemAfter.locator('.task-toggle').textContent();
assert.equal(btnTextAfter, '未完成任务', 'AC-004: 回退后按钮应显示未完成');

// 业务断言：aria-pressed 恢复 false
const ariaAfter = await itemAfter.locator('.task-toggle').getAttribute('aria-pressed');
assert.equal(ariaAfter, 'false', 'AC-004: aria-pressed 应恢复为 false');

// 业务断言：li 不再有 done class
const itemClass = await itemAfter.getAttribute('class');
assert.ok(!itemClass.includes('done'), 'AC-004: 回退后不应标记 done 样式类');

// 业务断言：已完成统计归零
const doneStat = await page.locator('#stat-done').textContent();
assert.equal(doneStat, '0');

// 准备：新增一条任务（witness 证明 total 从 0 变为 1）
await page.fill('#task-input', '待删除任务');
await runtimeWitness(page, {
  getter: 'window.app.getDerived',
  state_path: 'total',
  action: { kind: 'click', selector: '#btn-add' },
  view: { kind: 'number', selector: '#stat-total' }
});

// 确认任务存在于列表
assert.equal(await page.locator('.task-item').count(), 1);
const taskText = await page.locator('.task-item:first-child .task-text').textContent();
assert.equal(taskText.trim(), '待删除任务');

// 执行删除：witness total 从 1 变 0
await runtimeWitness(page, {
  getter: 'window.app.getDerived',
  state_path: 'total',
  action: { kind: 'click', selector: '.task-item:first-child .task-delete' },
  view: { kind: 'number', selector: '#stat-total' }
});

// 验证任务不再显示在列表中
assert.equal(await page.locator('.task-item').count(), 0);

// 验证统计数字全部归零
assert.equal((await page.locator('#stat-total').textContent()).trim(), '0');
assert.equal((await page.locator('#stat-active').textContent()).trim(), '0');
assert.equal((await page.locator('#stat-done').textContent()).trim(), '0');

// 验证无残留：列表 ul 内无子元素
const listChildren = await page.locator('#task-list').evaluate((el) => el.children.length);
assert.equal(listChildren, 0);

// 验证空列表提示出现（页面不白屏）
const emptyVisible = await page.locator('#empty-tip').isVisible();
assert.ok(emptyVisible);

// 验证内部状态也清空
const derived = await page.evaluate(() => window.app.getDerived());
assert.equal(derived.total, 0);
assert.equal(derived.visibleTasks.length, 0);

// 准备：新增三条任务
await page.fill('#task-input', '任务A');
await runtimeWitness(page, {
  getter: 'window.app.getDerived',
  state_path: 'total',
