async function getStats() {
  return {
    total: Number(await page.locator('#stat-total').textContent()),
    active: Number(await page.locator('#stat-active').textContent()),
    done: Number(await page.locator('#stat-done').textContent())
  };
}

async function assertStats(expectedTotal, expectedActive, expectedDone, step) {
  const s = await getStats();
  assert.equal(s.total, expectedTotal, step + ' total');
  assert.equal(s.active, expectedActive, step + ' active');
  assert.equal(s.done, expectedDone, step + ' done');
  assert.equal(s.total, s.active + s.done, step + ' consistency');
}

