const mobileCtx = await context.browser().newContext({ viewport: { width: 375, height: 667 }, hasTouch: true, isMobile: true });
try {
  const mPage = await mobileCtx.newPage();
  await mPage.goto(baseURL, { waitUntil: 'domcontentloaded' });
  await mPage.waitForSelector('#task-input');
  const long = '非常长的任务内容'.repeat(20);
