  await mPage.tap('#btn-add');
  assert.equal(await mPage.locator('.task-item').count(), 1, '移动视口成功新增超长文本任务');
  const geo = await mPage.evaluate(() => {
    const vw = document.documentElement.clientWidth;
    const item = document.querySelector('.task-item');
    const text = document.querySelector('.task-text');
    const itemRect = item.getBoundingClientRect();
    return {
      vw: vw,
      bodyScrollWidth: document.body.scrollWidth,
      docScrollWidth: document.documentElement.scrollWidth,
      itemRight: itemRect.right,
      itemLeft: itemRect.left,
      textScroll: text.scrollWidth,
      textClient: text.clientWidth
    };
  });
  assert.ok(geo.docScrollWidth <= geo.vw, '移动视口页面根元素无横向溢出，布局未被破坏');
  assert.ok(geo.itemRight <= geo.vw + 1, '移动视口任务项右边界未超出视口宽度');
  assert.ok(geo.itemLeft >= 0, '移动视口任务项左边界在视口内');
  assert.ok(geo.textScroll <= geo.textClient + 1, '移动视口任务文本在容器内换行不横向溢出');
} finally {
  await mobileCtx.close();
}

