import type { AppState, Filter, DerivedState } from './types.ts';
import { addTask, toggleTask, deleteTask, setFilter, derive } from './store.ts';
import { loadTasks, saveTasks } from './storage.ts';
import { createApp } from './ui.ts';

const state: AppState = { tasks: [], filter: 'all', storageAvailable: true };

function getState(): AppState {
  return { tasks: state.tasks.map((t) => ({ ...t })), filter: state.filter, storageAvailable: state.storageAvailable };
}

function getDerived(): DerivedState {
  return derive(state);
}

function persist(): void {
  const ok = saveTasks(state.tasks);
  state.storageAvailable = ok;
}

function boot(): void {
  const loaded = loadTasks();
  state.tasks = loaded.tasks;
  state.storageAvailable = loaded.available;

  const root = document.getElementById('app');
  if (!root) return;

  const ui = createApp(root, {
    onAdd(raw: string) {
      const result = addTask(state.tasks, raw);
      if (result.error) {
        ui.render(state, result.error);
        return;
      }
      state.tasks = result.tasks;
      persist();
      ui.render(state);
    },
    onToggle(id: string) {
      state.tasks = toggleTask(state.tasks, id);
      persist();
      ui.render(state);
    },
    onDelete(id: string) {
      state.tasks = deleteTask(state.tasks, id);
      persist();
      ui.render(state);
    },
    onFilter(next: Filter) {
      state.filter = setFilter(state.filter, next);
      ui.render(state);
    },
  });

  ui.render(state);

  const w = window as unknown as { app: { getState: typeof getState; getDerived: typeof getDerived } };
  w.app = { getState, getDerived };
}

if (typeof document !== 'undefined') {
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', boot);
  } else {
    boot();
  }
}

export { getState, getDerived, boot };

