import type { Task } from './types.ts';

export const STORAGE_KEY = 'task-list-data';

/** 可注入的存储接口，便于测试用 mock 对象替代真实 localStorage。 */
export interface StorageLike {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
}

/** 安全解析存储句柄：读取属性异常时返回 null。 */
function resolveStorage(injected?: StorageLike | null): StorageLike | null {
  if (injected) return injected;
  try {
    const ls = (globalThis as unknown as { localStorage?: StorageLike }).localStorage;
    if (ls && typeof ls.getItem === 'function' && typeof ls.setItem === 'function') {
      return ls;
    }
    return null;
  } catch {
    return null;
  }
}

function isTask(x: unknown): x is Task {
  return (
    !!x &&
    typeof x === 'object' &&
    typeof (x as Task).id === 'string' &&
    typeof (x as Task).text === 'string' &&
    typeof (x as Task).done === 'boolean'
  );
}

/**
 * 读取持久化任务。任何异常（属性访问/读取/解析/格式非法）都降级为
 * available=false，并返回空数组与可理解错误，绝不抛出。
 */
export function loadTasks(injected?: StorageLike | null): { tasks: Task[]; available: boolean; error?: string } {
  const storage = resolveStorage(injected);
  if (!storage) {
    return { tasks: [], available: false, error: '浏览器本地存储不可用。' };
  }
  let raw: string | null;
  try {
    raw = storage.getItem(STORAGE_KEY);
  } catch {
    return { tasks: [], available: false, error: '读取本地存储失败。' };
  }
  if (raw === null || raw === undefined) {
    return { tasks: [], available: true };
  }
  try {
    const parsed = JSON.parse(raw);
    const arr = Array.isArray(parsed)
      ? parsed
      : parsed && typeof parsed === 'object' && Array.isArray((parsed as { tasks?: unknown }).tasks)
        ? (parsed as { tasks: unknown[] }).tasks
        : null;
    if (!Array.isArray(arr)) {
      return { tasks: [], available: false, error: '本地存储数据格式无法识别。' };
    }
    const tasks: Task[] = arr.filter(isTask).map((t) => ({ id: t.id, text: t.text, done: t.done }));
    return { tasks, available: true };
  } catch {
    return { tasks: [], available: false, error: '本地存储数据已损坏，无法解析。' };
  }
}

/**
 * 写入持久化任务。任何异常返回 false，不抛出，供调用方降级。
 * 持久化同时包含 text 与 done 字段（AC-012）。
 */
export function saveTasks(tasks: Task[], injected?: StorageLike | null): boolean {
  const storage = resolveStorage(injected);
  if (!storage) return false;
  try {
    const payload = { tasks: tasks.map((t) => ({ id: t.id, text: t.text, done: t.done })) };
    storage.setItem(STORAGE_KEY, JSON.stringify(payload));
    return true;
  } catch {
    return false;
  }
}

