import type { Task, Filter, AppState, DerivedState } from './types.ts';

function genId(): string {
  return 't_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 8);
}

/**
 * 校验并新增任务：去除首尾空白，空（含纯空白）则拒绝并返回可理解错误。
 */
export function addTask(tasks: Task[], rawText: string): { tasks: Task[]; error?: string } {
  const text = (typeof rawText === 'string' ? rawText : '').replace(/^[\s\uFEFF\xA0]+|[\s\uFEFF\xA0]+$/g, '');
  if (text.length === 0) {
    return { tasks, error: '请输入任务内容，不能为空或纯空白字符。' };
  }
  const task: Task = { id: genId(), text, done: false };
  return { tasks: [...tasks, task] };
}

/** 切换完成状态，不改变任务文本。 */
export function toggleTask(tasks: Task[], id: string): Task[] {
  return tasks.map((t) => (t.id === id ? { ...t, done: !t.done } : t));
}

/** 删除任务，不残留。 */
export function deleteTask(tasks: Task[], id: string): Task[] {
  return tasks.filter((t) => t.id !== id);
}

/** 设置筛选，仅返回新筛选值，不修改任务数据。 */
export function setFilter(_current: Filter, next: Filter): Filter {
  return next;
}

/** 派生统计与可见任务；保证 总数 = 未完成 + 已完成。 */
export function derive(state: AppState): DerivedState {
  const total = state.tasks.length;
  const doneCount = state.tasks.reduce((n, t) => n + (t.done ? 1 : 0), 0);
  const activeCount = total - doneCount;
  let visibleTasks: Task[];
  if (state.filter === 'active') {
    visibleTasks = state.tasks.filter((t) => !t.done);
  } else if (state.filter === 'done') {
    visibleTasks = state.tasks.filter((t) => t.done);
  } else {
    visibleTasks = state.tasks.map((t) => ({ ...t }));
  }
  return {
    total,
    activeCount,
    doneCount,
    visibleTasks,
    filter: state.filter,
    storageAvailable: state.storageAvailable,
  };
}

