import type { AppState, DerivedState, Filter, Task } from './types.ts';
import { derive } from './store.ts';

export interface UIHandlers {
  onAdd: (rawText: string) => void;
  onToggle: (id: string) => void;
  onDelete: (id: string) => void;
  onFilter: (filter: Filter) => void;
}

const FILTER_LABELS: Record<Filter, string> = {
  all: '全部',
  active: '未完成',
  done: '已完成',
};

function el<K extends keyof HTMLElementTagNameMap>(
  tag: K,
  attrs: Record<string, string> = {},
  text?: string,
): HTMLElementTagNameMap[K] {
  const node = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) node.setAttribute(k, v);
  if (text !== undefined) node.textContent = text;
  return node;
}

export function createApp(root: HTMLElement, handlers: UIHandlers): { render: (state: AppState, error?: string) => void } {
  root.innerHTML = '';

  const heading = el('h1', { class: 'app-title' }, '离线任务清单');

  // 存储警告（降级提示）
  const storageWarning = el('p', { id: 'storage-warning', class: 'storage-warning', role: 'status' }, '');
  storageWarning.hidden = true;

  // 输入区
  const label = el('label', { for: 'task-input' }, '任务内容');
  const input = el('input', {
    id: 'task-input',
    type: 'text',
    name: 'task',
    autocomplete: 'off',
    placeholder: '输入任务内容',
    'aria-label': '任务内容',
  });
  const addBtn = el('button', { id: 'btn-add', type: 'button', 'aria-label': '新增任务' }, '新增');
  const errorMsg = el('p', { id: 'error-msg', class: 'error-msg', role: 'alert', 'aria-live': 'assertive' }, '');

  const inputRow = el('div', { class: 'input-row' });
  inputRow.append(label, input, addBtn);

  // 统计区
  const stats = el('div', { class: 'stats', role: 'status', 'aria-label': '任务统计' });
  const totalSpan = el('span', { class: 'stat' }, '');
  totalSpan.append(el('span', {}, '总数：'), el('b', { id: 'stat-total' }, '0'));
  const activeSpan = el('span', { class: 'stat' }, '');
  activeSpan.append(el('span', {}, '未完成：'), el('b', { id: 'stat-active' }, '0'));
  const doneSpan = el('span', { class: 'stat' }, '');
  doneSpan.append(el('span', {}, '已完成：'), el('b', { id: 'stat-done' }, '0'));
  stats.append(totalSpan, activeSpan, doneSpan);

  // 筛选区
  const filterGroup = el('div', { class: 'filters', role: 'group', 'aria-label': '筛选视图' });
  const filterButtons: Record<Filter, HTMLButtonElement> = { all: undefined as unknown as HTMLButtonElement, active: undefined as unknown as HTMLButtonElement, done: undefined as unknown as HTMLButtonElement };
  (['all', 'active', 'done'] as Filter[]).forEach((f) => {
    const btn = el('button', {
      type: 'button',
      class: 'filter-btn',
      'data-filter': f,
      'aria-pressed': 'false',
      'aria-label': '筛选：' + FILTER_LABELS[f],
    }, FILTER_LABELS[f]);
    btn.addEventListener('click', () => handlers.onFilter(f));
    filterButtons[f] = btn;
    filterGroup.append(btn);
  });

  // 列表
  const list = el('ul', { id: 'task-list', class: 'task-list' });
  const emptyTip = el('p', { id: 'empty-tip', class: 'empty-tip' }, '暂无任务。');

  root.append(heading, storageWarning, inputRow, errorMsg, stats, filterGroup, list, emptyTip);

  input.addEventListener('keydown', (e) => {
    const ke = e as KeyboardEvent;
    if (ke.key === 'Enter') {
      ke.preventDefault();
      handlers.onAdd((document.getElementById('task-input') as HTMLInputElement).value);
    }
  });
  addBtn.addEventListener('click', () => {
    handlers.onAdd((document.getElementById('task-input') as HTMLInputElement).value);
  });

  function renderTaskItem(task: Task): HTMLLIElement {
    const li = el('li', { class: 'task-item' + (task.done ? ' done' : '') });
    li.setAttribute('data-id', task.id);

    const toggle = el('button', {
      type: 'button',
      class: 'task-toggle',
      'aria-pressed': task.done ? 'true' : 'false',
      'aria-label': '切换完成状态：' + task.text,
    }, task.done ? '已完成' : '未完成');
    toggle.addEventListener('click', () => handlers.onToggle(task.id));

    const textSpan = el('span', { class: 'task-text', 'aria-hidden': 'false' }, task.text);

    const del = el('button', {
      type: 'button',
      class: 'task-delete',
      'aria-label': '删除任务：' + task.text,
    }, '删除');
    del.addEventListener('click', () => handlers.onDelete(task.id));

    li.append(toggle, textSpan, del);
    return li;
  }

  const totalEl = () => document.getElementById('stat-total') as HTMLElement;
  const activeEl = () => document.getElementById('stat-active') as HTMLElement;
  const doneEl = () => document.getElementById('stat-done') as HTMLElement;

  function render(state: AppState, error?: string): void {
    const d: DerivedState = derive(state);

    // 统计
    totalEl().textContent = String(d.total);
    activeEl().textContent = String(d.activeCount);
    doneEl().textContent = String(d.doneCount);

    // 筛选态
    (['all', 'active', 'done'] as Filter[]).forEach((f) => {
      filterButtons[f].setAttribute('aria-pressed', f === d.filter ? 'true' : 'false');
    });

    // 列表
    list.innerHTML = '';
    const frag = document.createDocumentFragment();
    for (const t of d.visibleTasks) frag.append(renderTaskItem(t));
    list.append(frag);

    // 空提示：无任务或当前筛选无匹配
    emptyTip.hidden = d.visibleTasks.length !== 0;
    if (d.visibleTasks.length === 0) {
      emptyTip.textContent = state.tasks.length === 0 ? '暂无任务，请新增一条。' : '当前筛选下没有匹配的任务。';
    }

    // 错误提示
    errorMsg.textContent = error && error.length > 0 ? error : '';
    errorMsg.hidden = !(error && error.length > 0);
    // 新增成功后清空输入框
    if (!error) input.value = '';

    // 存储警告
    if (state.storageAvailable) {
      storageWarning.hidden = true;
      storageWarning.textContent = '';
    } else {
      storageWarning.hidden = false;
      storageWarning.textContent = '保存不可用：修改仅在当前会话内生效，不会持久化。';
    }
  }

  return { render };
}

