// isolated_logic：组合 store + storage 模拟完整用户场景序列，纯 Node，不使用 jsdom。
import { test } from 'node:test';
import assert from 'node:assert/strict';

import { addTask, toggleTask, deleteTask, setFilter, derive } from '../src/store.ts';
import { loadTasks, saveTasks, STORAGE_KEY } from '../src/storage.ts';
import type { StorageLike } from '../src/storage.ts';
import type { AppState, Task, Filter } from '../src/types.ts';

function memStorage(seed: Record<string, string> = {}): StorageLike & { data: Record<string, string> } {
  const data: Record<string, string> = { ...seed };
  return {
    data,
    getItem(key: string) {
      return Object.prototype.hasOwnProperty.call(data, key) ? data[key] : null;
    },
    setItem(key: string, value: string) {
      data[key] = value;
    },
  };
}

// 场景：初始化恢复 → 新增 → 切换 → 删除 → 筛选不篡改 → 刷新恢复。
test('完整场景：增删改切与持久化恢复', () => {
  const storage = memStorage();
  const state: AppState = { tasks: [], filter: 'all', storageAvailable: true };

  const persist = () => {
    state.storageAvailable = saveTasks(state.tasks, storage);
  };

  // 1) 初始化恢复（空存储）。
  const loaded = loadTasks(storage);
  state.tasks = loaded.tasks;
  state.storageAvailable = loaded.available;
  assert.equal(state.tasks.length, 0);
  assert.equal(derive(state).total, 0);

  // 2) AC-001/AC-002 新增有效任务（含首尾空白被去除）。
  let r = addTask(state.tasks, '  学习  ');
  assert.equal(r.error, undefined);
  state.tasks = r.tasks;
  persist();
  assert.equal(derive(state).total, 1);

  r = addTask(state.tasks, '买菜');
  state.tasks = r.tasks;
  persist();

  r = addTask(state.tasks, '写周报');
  state.tasks = r.tasks;
  persist();

  // 3) AC-003 空白拒绝，不增加。
  const before = state.tasks.length;
  const bad = addTask(state.tasks, '   ');
  assert.ok(bad.error);
  assert.equal(bad.tasks.length, before);

  // 4) AC-004 切换完成状态。
  const learnId = state.tasks.find((t) => t.text === '学习')!.id;
  state.tasks = toggleTask(state.tasks, learnId);
  persist();
  let d = derive(state);
  assert.equal(d.doneCount, 1);
  assert.equal(d.activeCount, 2);
  assert.equal(d.total, 3);

  // 5) AC-006/AC-007 一致性。
  assert.equal(d.total, d.activeCount + d.doneCount);

  // 6) AC-008 筛选可见集合，且不篡改（AC-009）。
  const snapshot: Task[] = state.tasks.map((t) => ({ ...t }));
  const seq: Filter[] = ['active', 'done', 'all', 'done', 'active'];
  for (const f of seq) {
    state.filter = setFilter(state.filter, f);
    const dv = derive(state);
    if (f === 'active') assert.ok(dv.visibleTasks.every((t) => !t.done));
    else if (f === 'done') assert.ok(dv.visibleTasks.every((t) => t.done));
    assert.equal(dv.total, 3);
  }
  state.filter = 'all';
  assert.deepEqual(state.tasks, snapshot); // 反复筛选后数据不变

  // 7) AC-005 删除一条。
  const buyId = state.tasks.find((t) => t.text === '买菜')!.id;
  state.tasks = deleteTask(state.tasks, buyId);
  persist();
  d = derive(state);
  assert.equal(d.total, 2);
  assert.ok(!d.visibleTasks.some((t) => t.id === buyId));

  // 8) AC-011/AC-012 刷新恢复：从同一存储重新加载。
  const reload = loadTasks(storage);
  assert.equal(reload.available, true);
  const reloadedState: AppState = { tasks: reload.tasks, filter: 'all', storageAvailable: reload.available };
  const rd = derive(reloadedState);
  assert.equal(rd.total, 2);
  assert.equal(rd.doneCount, 1);
  assert.equal(rd.activeCount, 1);
  const learnRestored = reloadedState.tasks.find((t) => t.text === '学习');
  assert.ok(learnRestored && learnRestored.done === true);
});

// AC-010 空列表提示判定（无任务 / 筛选无匹配）。
test('空列表提示判定', () => {
  const empty: AppState = { tasks: [], filter: 'all', storageAvailable: true };
  assert.equal(derive(empty).visibleTasks.length, 0); // 全局空 → 显示“暂无任务”

  const all: AppState = {
    tasks: [
      { id: 'a', text: 'A', done: false },
      { id: 'b', text: 'B', done: true },
    ],
    filter: 'all',
    storageAvailable: true,
  };
  // 有任务但当前筛选无匹配：全部完成时用 active 筛选。
  all.tasks = all.tasks.map((t) => ({ ...t, done: true }));
  all.filter = 'active';
  assert.equal(derive(all).visibleTasks.length, 0); // 筛选无匹配 → 显示“当前筛选下没有匹配”
});

// AC-013/AC-014/AC-015 存储降级：会话内仍可正常增删改切，且计数即时生效。
test('存储故障降级会话内功能仍正常', () => {
  const storage: StorageLike = {
    getItem() {
      throw new Error('storage blocked');
    },
    setItem() {
      throw new Error('storage blocked');
    },
  };

  const loaded = loadTasks(storage);
  assert.equal(loaded.available, false); // 降级标记

  const state: AppState = { tasks: loaded.tasks, filter: 'all', storageAvailable: loaded.available };
  assert.equal(state.storageAvailable, false);

  // 会话内新增：saveTasks 返回 false，功能仍生效。
  const r = addTask(state.tasks, '降级新增');
  state.tasks = r.tasks;
  const savedOk = saveTasks(state.tasks, storage);
  state.storageAvailable = savedOk;
  assert.equal(savedOk, false);
  assert.equal(state.storageAvailable, false);
  assert.equal(derive(state).total, 1);

  // 会话内切换。
  const id = state.tasks[0].id;
  state.tasks = toggleTask(state.tasks, id);
  saveTasks(state.tasks, storage);
  assert.equal(derive(state).doneCount, 1);

  // 会话内删除。
  state.tasks = deleteTask(state.tasks, id);
  saveTasks(state.tasks, storage);
  const d = derive(state);
  assert.equal(d.total, 0);
  assert.equal(d.activeCount + d.doneCount, d.total);
});

// 解析失败内容降级，会话继续可用。
test('损坏存储内容触发降级后继续操作', () => {
  const storage = memStorage();
  storage.setItem(STORAGE_KEY, 'not-json{[');
  const loaded = loadTasks(storage);
  assert.equal(loaded.available, false);
  assert.deepEqual(loaded.tasks, []);

  const state: AppState = { tasks: loaded.tasks, filter: 'all', storageAvailable: loaded.available };
  const r = addTask(state.tasks, '修复后任务');
  state.tasks = r.tasks;
  assert.equal(derive(state).total, 1);
});

