// isolated_logic：存储模块测试，注入 mock 对象模拟 localStorage，不使用 jsdom。
import { test } from 'node:test';
import assert from 'node:assert/strict';

import { loadTasks, saveTasks, STORAGE_KEY } from '../src/storage.ts';
import type { StorageLike } from '../src/storage.ts';
import type { Task } from '../src/types.ts';

// 可抛异常的内存存储 mock，记录调用。
function memStorage(seed: Record<string, string> = {}): StorageLike & { data: Record<string, string> } {
  const data: Record<string, string> = { ...seed };
  return {
    data,
    getItem(key: string) {
      return Object.prototype.hasOwnProperty.call(data, key) ? data[key] : null;
    },
    setItem(key: string, value: string) {
      data[key] = value;
    },
  };
}

function throwingGetItem(): StorageLike {
  return {
    getItem() {
      throw new Error('getItem blocked');
    },
    setItem() {},
  };
}

function throwingSetItem(): StorageLike {
  return {
    getItem() {
      return null;
    },
    setItem() {
      throw new Error('setItem blocked');
    },
  };
}

// AC-012 / AC-011 正常存取包含 text 与 done 字段。
test('saveTasks/loadTasks: 往返保存 text 与 done', () => {
  const storage = memStorage();
  const tasks: Task[] = [
    { id: 'a', text: '学习', done: true },
    { id: 'b', text: '买菜', done: false },
  ];
  const ok = saveTasks(tasks, storage);
  assert.equal(ok, true);

  // 持久化内容确实同时含 text 与 done 字段。
  const raw = storage.data[STORAGE_KEY];
  assert.ok(raw);
  const parsed = JSON.parse(raw);
  const arr = Array.isArray(parsed) ? parsed : parsed.tasks;
  assert.deepEqual(arr.map((t: Task) => t.text), ['学习', '买菜']);
  assert.deepEqual(arr.map((t: Task) => t.done), [true, false]);

  const loaded = loadTasks(storage);
  assert.equal(loaded.available, true);
  assert.deepEqual(loaded.tasks, tasks);
});

test('loadTasks: 空存储（无键）返回可用且空数组', () => {
  const loaded = loadTasks(memStorage());
  assert.equal(loaded.available, true);
  assert.deepEqual(loaded.tasks, []);
});

test('loadTasks: 兼容顶层数组格式', () => {
  const storage = memStorage();
  storage.setItem(STORAGE_KEY, JSON.stringify([{ id: 'x', text: '旧格式', done: true }]));
  const loaded = loadTasks(storage);
  assert.equal(loaded.available, true);
  assert.deepEqual(loaded.tasks, [{ id: 'x', text: '旧格式', done: true }]);
});

test('loadTasks: 过滤格式非法项', () => {
  const storage = memStorage();
  storage.setItem(STORAGE_KEY, JSON.stringify({ tasks: [{ id: 'a', text: 'OK', done: false }, { id: 1 }, null, 'oops'] }));
  const loaded = loadTasks(storage);
  assert.equal(loaded.available, true);
  assert.deepEqual(loaded.tasks, [{ id: 'a', text: 'OK', done: false }]);
});

// AC-014 非法 JSON 解析失败 → 降级 available=false。
test('loadTasks: 非法 JSON 降级', () => {
  const storage = memStorage();
  storage.setItem(STORAGE_KEY, '{ 这不是合法 JSON ]');
  const loaded = loadTasks(storage);
  assert.equal(loaded.available, false);
  assert.deepEqual(loaded.tasks, []);
  assert.ok(loaded.error && loaded.error.length > 0);
});

// AC-013 读取方法抛出异常 → 降级 available=false。
test('loadTasks: getItem 抛异常降级', () => {
  const loaded = loadTasks(throwingGetItem());
  assert.equal(loaded.available, false);
  assert.deepEqual(loaded.tasks, []);
});

// AC-013 存储不可用（无注入且环境无 localStorage）→ available=false。
test('loadTasks: 无 localStorage 环境降级', () => {
  // Node 默认无 globalThis.localStorage；显式清除以防污染。
  const prev = Object.getOwnPropertyDescriptor(globalThis, 'localStorage');
  try {
    // 定义一个读取属性即抛错的 getter，模拟“读取存储属性抛出异常”。
    Object.defineProperty(globalThis, 'localStorage', {
      configurable: true,
      get() {
        throw new Error('access blocked');
      },
    });
    const loaded = loadTasks();
    assert.equal(loaded.available, false);
    assert.deepEqual(loaded.tasks, []);
  } finally {
    if (prev) Object.defineProperty(globalThis, 'localStorage', prev);
    else delete (globalThis as unknown as { localStorage?: unknown }).localStorage;
  }
});

// AC-013 / AC-015 写方法抛异常 → saveTasks 返回 false 而不抛出。
test('saveTasks: setItem 抛异常返回 false 不抛出', () => {
  const ok = saveTasks([{ id: 'a', text: 'A', done: false }], throwingSetItem());
  assert.equal(ok, false);
});

test('saveTasks: 无存储环境返回 false', () => {
  const ok = saveTasks([{ id: 'a', text: 'A', done: false }], null);
  // Node 无 localStorage，注入为 null/undefined 走环境探测，返回 false。
  assert.equal(ok, false);
});

