// isolated_logic：纯状态逻辑测试，直接 import src/store.ts，不使用 jsdom。
import { test } from 'node:test';
import assert from 'node:assert/strict';

import { addTask, toggleTask, deleteTask, setFilter, derive } from '../src/store.ts';
