test('toggleTask: 不存在的 id 不改变其它任务', () => {
  const tasks = [mkTask('a', 'A'), mkTask('b', 'B')];
  const after = toggleTask(tasks, 'missing');
  assert.deepEqual(after.map((t) => t.done), [false, false]);
});

// AC-005 删除任务后移除、不残留。
test('deleteTask: 删除指定任务', () => {
  const tasks = [mkTask('a', 'A'), mkTask('b', 'B'), mkTask('c', 'C')];
  const after = deleteTask(tasks, 'b');
  assert.equal(after.length, 2);
  assert.ok(!after.some((t) => t.id === 'b'));
  assert.deepEqual(after.map((t) => t.id), ['a', 'c']);
});

test('deleteTask: 删除最后一个后列表为空且不残留', () => {
  const tasks = [mkTask('a', 'A')];
  const after = deleteTask(tasks, 'a');
  assert.equal(after.length, 0);
});

// AC-008 setFilter 仅返回新筛选值。
test('setFilter: 返回目标筛选值', () => {
  assert.equal(setFilter('all', 'active'), 'active');
  assert.equal(setFilter('active', 'done'), 'done');
  assert.equal(setFilter('done', 'all'), 'all');
});

// AC-006 / AC-007 derive 计数即时准确且总数 = 未完成 + 已完成。
test('derive: 计数与一致性', () => {
  const state: AppState = {
    tasks: [mkTask('a', 'A', false), mkTask('b', 'B', true), mkTask('c', 'C', true)],
    filter: 'all',
    storageAvailable: true,
  };
  const d = derive(state);
  assert.equal(d.total, 3);
  assert.equal(d.doneCount, 2);
  assert.equal(d.activeCount, 1);
  assert.equal(d.total, d.activeCount + d.doneCount);
  assert.equal(d.visibleTasks.length, 3);
});

test('derive: 空列表计数全为 0', () => {
  const state: AppState = { tasks: [], filter: 'all', storageAvailable: true };
  const d = derive(state);
  assert.equal(d.total, 0);
  assert.equal(d.activeCount, 0);
  assert.equal(d.doneCount, 0);
  assert.equal(d.visibleTasks.length, 0);
});

// AC-008 三种筛选可见集合正确。
test('derive: active 筛选仅显示未完成任务', () => {
  const state: AppState = {
    tasks: [mkTask('a', 'A', false), mkTask('b', 'B', true)],
    filter: 'active',
    storageAvailable: true,
  };
  const d = derive(state);
  assert.deepEqual(d.visibleTasks.map((t) => t.id), ['a']);
  assert.ok(d.visibleTasks.every((t) => !t.done));
});

test('derive: done 筛选仅显示已完成任务', () => {
  const state: AppState = {
    tasks: [mkTask('a', 'A', false), mkTask('b', 'B', true)],
    filter: 'done',
    storageAvailable: true,
  };
  const d = derive(state);
  assert.deepEqual(d.visibleTasks.map((t) => t.id), ['b']);
  assert.ok(d.visibleTasks.every((t) => t.done));
});

test('derive: all 筛选显示全部', () => {
  const state: AppState = {
    tasks: [mkTask('a', 'A', false), mkTask('b', 'B', true)],
    filter: 'all',
    storageAvailable: true,
  };
  const d = derive(state);
  assert.equal(d.visibleTasks.length, 2);
});

// AC-009 反复筛选不篡改文本与状态。
test('derive: 筛选不修改 state.tasks 内容', () => {
  const state: AppState = {
    tasks: [mkTask('a', 'A', false), mkTask('b', 'B', true)],
    filter: 'all',
    storageAvailable: true,
  };
  const snapshot = state.tasks.map((t) => ({ ...t }));
  const filters: Filter[] = ['active', 'done', 'all', 'done', 'active', 'all'];
  for (const f of filters) {
    state.filter = setFilter(state.filter, f);
    derive(state);
  }
  assert.deepEqual(state.tasks, snapshot);
});

