    "script": "// 前置：清除可能残留的存储数据
await page.evaluate(() => localStorage.clear());
await page.goto(baseURL, { waitUntil: 'networkidle' });

// 场景准备：输入有效文本（fill 不作为 witness）
await page.fill('#task-input', '学习 TypeScript');

// witness：点击新增按钮 → total 从 0 变 1
await runtimeWitness(page, {
  getter: 'window.app.getDerived',
  state_path: 'total',
  action: { kind: 'click', selector: '#btn-add' },
  view: { kind: 'number', selector: '#stat-total' }
});

// 再添加一条任务用于后续切换
await page.fill('#task-input', '买菜');
await runtimeWitness(page, {
  getter: 'window.app.getDerived',
  state_path: 'total',
  action: { kind: 'click', selector: '#btn-add' },
  view: { kind: 'number', selector: '#stat-total' }
});

// 切换第一条任务为已完成
await runtimeWitness(page, {
  getter: 'window.app.getDerived',
  state_path: 'doneCount',
  action: { kind: 'click', selector: '.task-item:first-child .task-toggle' },
  view: { kind: 'number', selector: '#stat-done' }
});

// 关键验证：读取 localStorage 原始数据，确认同时包含 text 和 done 字段
const rawStored = await page.evaluate(() => {
  return localStorage.getItem('task-list-data');
});
assert.ok(rawStored, 'localStorage 中应存在 task-list-data 键');

const parsed = JSON.parse(rawStored);
// 验证格式为对象含 tasks 数组（或顶层数组）
const tasksArray = Array.isArray(parsed) ? parsed : parsed.tasks;
assert.ok(Array.isArray(tasksArray), '存储数据应包含任务数组');
assert.equal(tasksArray.length, 2, '应持久化 2 条任务');

// 验证每条任务同时含 text 和 done 字段
for (const t of tasksArray) {
