  for (var i = 0; i < lines.length; i++) {
    var m = lines[i].match(/^ok\s+\d+\s+-\s+(.+)/);
    if (m) names.push(m[1]);
  }
}

// 拼接全部名称为小写用于关键词匹配
var allNames = names.join(' ').toLowerCase();

// 验证各必需场景的覆盖
// 新增 (add)
assert.ok(allNames.includes('add') || allNames.includes('新增'), '测试须覆盖新增场景，可用名称: ' + allNames.substring(0, 500));

// 空白拒绝 (空白/空/reject/empty/纯空格)
assert.ok(
  allNames.includes('空白') || allNames.includes('空字符串') || allNames.includes('拒绝') ||
  allNames.includes('reject') || allNames.includes('empty') || allNames.includes('纯空格'),
  '测试须覆盖空白拒绝场景'
);

// 切换完成 (toggle/切换)
assert.ok(
  allNames.includes('toggle') || allNames.includes('切换'),
  '测试须覆盖完成切换场景'
);

// 计数一致性 (derive/计数/一致性/consistency/统计)
assert.ok(
  allNames.includes('derive') || allNames.includes('计数') || allNames.includes('一致性') ||
  allNames.includes('consistency') || allNames.includes('统计'),
  '测试须覆盖计数一致性场景'
);

// 筛选 (filter/筛选)
assert.ok(
  allNames.includes('filter') || allNames.includes('筛选'),
  '测试须覆盖筛选场景'
);

// 删除 (delete/删除)
assert.ok(
  allNames.includes('delete') || allNames.includes('删除'),
  '测试须覆盖删除场景'
);

// 刷新恢复/持久化 (恢复/往返/load/persist/存储/存取)
assert.ok(
  allNames.includes('恢复') || allNames.includes('往返') || allNames.includes('persist') ||
  allNames.includes('load') || allNames.includes('存取') || allNames.includes('保存') ||
  allNames.includes('save') || allNames.includes('完整场景'),
  '测试须覆盖刷新恢复/持久化场景'
);

// 存储降级 (降级/throwing/blocked/不可用/非法/损坏/故障)
assert.ok(
  allNames.includes('降级') || allNames.includes('throwing') || allNames.includes('blocked') ||
  allNames.includes('不可用') || allNames.includes('非法') || allNames.includes('损坏') ||
  allNames.includes('故障') || allNames.includes('不抛出'),
  '测试须覆盖存储降级场景'
);

