// AC-020 补充验证：应用作为交付物可独立启动访问
// 导航到应用入口确认可正常加载
await page.goto(baseURL, { waitUntil: 'networkidle' });

// 验证核心 DOM 元素存在（证明构建产物正确，交付物完整）
var input = await page.locator('#task-input').count();
assert.ok(input > 0, '应用须包含输入框 #task-input（可独立运行）');

var addBtn = await page.locator('#btn-add').count();
assert.ok(addBtn > 0, '应用须包含新增按钮 #btn-add');

var taskList = await page.locator('#task-list').count();
assert.ok(taskList > 0, '应用须包含任务列表 #task-list');

var statTotal = await page.locator('#stat-total').count();
assert.ok(statTotal > 0, '应用须包含统计元素 #stat-total');

var filterAll = await page.locator('[data-filter="all"]').count();
var filterActive = await page.locator('[data-filter="active"]').count();
var filterDone = await page.locator('[data-filter="done"]').count();
assert.ok(filterAll > 0 && filterActive > 0 && filterDone > 0, '应用须包含三种筛选按钮');

// 验证 window.app.getDerived 暴露（供 witness/集成验证使用）
var derived = await page.evaluate(function() {
  if (window.app && typeof window.app.getDerived === 'function') {
    return window.app.getDerived();
  }
  return null;
});
assert.ok(derived !== null, 'window.app.getDerived 须可调用');
assert.equal(typeof derived.total, 'number', 'getDerived 返回 total 为 number');
assert.equal(typeof derived.activeCount, 'number', 'getDerived 返回 activeCount 为 number');
assert.equal(typeof derived.doneCount, 'number', 'getDerived 返回 doneCount 为 number');
assert.equal(typeof derived.filter, 'string', 'getDerived 返回 filter 为 string');
assert.equal(typeof derived.storageAvailable, 'boolean', 'getDerived 返回 storageAvailable 为 boolean');

// 验证 README 存在且包含启动说明（通过检查应用正常构建可间接证明）
// 如果应用能从 dist/ 加载，说明构建成功，交付物完整
var title = await page.title();
assert.ok(title.length > 0, '页面标题非空（证明构建产物正确部署）');

