// AC-020 验证测试不是空/占位的——通过浏览器实际操作确认被测功能真实存在
// 如果测试只是占位，应用功能不会真正工作
await page.goto(baseURL, { waitUntil: 'networkidle' });

// 实际操作：新增任务（测试声称覆盖 addTask）
await page.fill('#task-input', '测试占位验证');
await page.click('#btn-add');

var totalAfterAdd = await page.evaluate(function() {
  return window.app.getDerived().total;
});
assert.equal(totalAfterAdd, 1, '新增后 total 应为 1（功能真实存在，非占位）');

// 实际操作：切换完成（测试声称覆盖 toggleTask）
await page.click('.task-item .task-toggle');
var derivedAfterToggle = await page.evaluate(function() {
  return window.app.getDerived();
});
assert.equal(derivedAfterToggle.doneCount, 1, '切换后 doneCount 应为 1');
assert.equal(derivedAfterToggle.activeCount, 0, '切换后 activeCount 应为 0');

// 实际操作：筛选不篡改（测试声称覆盖 setFilter/derive 筛选）
await page.click('[data-filter="done"]');
var visibleCount = await page.locator('.task-item').count();
assert.equal(visibleCount, 1, '已完成筛选下应显示 1 条');

await page.click('[data-filter="all"]');
var allVisible = await page.locator('.task-item').count();
assert.equal(allVisible, 1, '全部筛选下仍显示 1 条（筛选不篡改数据）');

// 验证数据未被筛选改变
taskText = await page.locator('.task-item .task-text').textContent();
assert.equal(taskText, '测试占位验证', '任务文本在筛选操作后保持不变');

// 实际操作：删除（测试声称覆盖 deleteTask）
await page.click('.task-item .task-delete');
var totalAfterDelete = await page.evaluate(function() {
  return window.app.getDerived().total;
});
assert.equal(totalAfterDelete, 0, '删除后 total 应为 0');

// 验证空列表提示（测试声称覆盖 emptyTip 逻辑）
var emptyTipVisible = await page.locator('#empty-tip').isVisible();
assert.ok(emptyTipVisible, '无任务时空提示可见');

// 综合验证：unitEvidence 中的测试数量与上述操作所验证的功能一致
// 如果测试为空/占位，不可能覆盖以上所有真实交互的验证逻辑
assert.ok(unitEvidence.status === 'passed', '以上功能验证通过且单测也通过——互相印证');
assert.ok(unitEvidence.tests >= 10, '足够的测试数量（' + unitEvidence.tests + '）覆盖以上全部场景');
